import TipTap from "@/types/TipTap";
import Element from "@/types/elements/Element";

class TABLE {
  header?: string;
  rows?: TABLE_CELL[][]
}

class TABLE_CELL {
  html = "";
  width?: number;
}

// TODO: Combine with getBulletPoints
function parseParagraph(json: TipTap[] | undefined): string {
  let htmlString = '';
  if (!json || json[0].content?.length === 0) return '';
  json.forEach((paragraph) => {
    paragraph.content?.forEach((item) => {
      if (!item.marks) htmlString += item.text;
      else {
        let textStart = "";
        let textEnd = "";
        item.marks.forEach(mark => {
          const type = mark.type;
          switch (type) {
            case "italic":
              textStart += '<i>';
              textEnd += '</i>'
              break;
            case "bold":
              textStart += '<strong>';
              textEnd += '</strong>'
              break;
            case "link":
              textStart += `<a href="${mark.attrs?.href}" style="font-family:Roboto,sans-serif;font-size:15px;color:#257886;text-decoration:underline;" target="_blank">`;
              textEnd += '</a>'
              break;
            case "subscript":
              textStart += '<sub>';
              textEnd += '</sub>'
              break;
            case "superscript":
              textStart += '<sup>';
              textEnd += '</sup>'
              break;
            case "textStyle":
              if (mark.attrs?.color === "rgb(237, 125, 49)" || String(mark.attrs?.color).toLowerCase() === "#fb4f00" ||
                  mark.attrs?.color?.color === "rgb(237, 125, 49)" || String(mark.attrs?.color?.color).toLowerCase() === "#fb4f00") {
                textStart += '<span style="color: #fb4f00">';
                textEnd += '</span>'
              }
              break;
          }
        });
        htmlString += textStart + item.text + textEnd;
      }
    })
  })
  return htmlString;
}

export function getTable(json: TipTap): TABLE {
  const tableClass: TABLE = { header: "", rows: [] };

  if (!json.content || json.content.length === 0) return tableClass;

  json.content.forEach(table => {
    if (table.type !== "table") return;

    table.content?.forEach((tableRow) => {
      if (!tableRow.content) return;

      const tableCells: TABLE_CELL[] = [];

      for (const item of tableRow.content) {
        if (item.type === "tableCell") {
          tableCells.push({
            html: parseParagraph(item.content),
            width: item.attrs?.colwidth?.[0],
          });
        } else if (item.type === "tableHeader") {
          tableClass.header = parseParagraph(item.content);
        }
      }

      tableClass.rows!.push(tableCells);
    });
  });

  return tableClass;
}

export default function getTableHTML(element: Element): string {
  const table = getTable(element.options.text);

  let tableHtml = `<table border="0" cellpadding="0" cellspacing="0" style="max-width:${element.options.padding > 0 ? "600px" : "560px"};${element.options.padding > 1 ? "padding:20px;": ""}font-family:Roboto,sans-serif;font-size:16px;color:#512b2b;border-radius:12px;overflow:hidden;background-color:${element.options.background ? "#FFFFFF" : ""};">`;

  if (element.options.headerEnabled && table.rows) {
    const maxColumnCount = Math.max(...table.rows.map(row => row?.length || 0), 1);

    // Each real column has a gap column between it and the next real column.
    // Example:
    // 2 cols = content, gap, content = colspan 3
    // 3 cols = content, gap, content, gap, content = colspan 5
    const headerColspan = maxColumnCount * 2 - 1;

    tableHtml += `
      <tr>
        ${element.options.padding > 0 ? '<td width="20" style="border-bottom:1px solid #ebe7e2">&nbsp;</td>' : ""}
        <td width="560" colspan="${headerColspan}" style="font-family:Roboto,sans-serif;font-weight:bold;font-size:20px;line-height:28px;color:#512b2b;border-bottom:1px solid #ebe7e2;padding:12px 0;">
          <span style="font-family:Roboto,sans-serif;font-weight:700;color:${element.options.headerColor}">${element.options.header.trim() === "" ? "Heading" : element.options.header}</span>
        </td>
        ${element.options.padding > 0 ? '<td width="20" style="border-bottom:1px solid #ebe7e2">&nbsp;</td>' : ""}
      </tr>
    `;
  }


  for (const [rowIndex, row] of (table.rows || []).entries()) {
    if (!row || row.length === 0) continue;

    const rowBackground = element.options.background && rowIndex % 2 === 1 ? "background-color:#fdf6ee;" : "";
    const cellWidths = getResolvedCellWidths(row, 560, 12);


    tableHtml += `
      <tr>
        ${element.options.padding > 0 ? `<td width="20" style="${rowBackground}">&nbsp;</td>` : ""}
    `;

    row.forEach((cell, cellIndex) => {
      tableHtml += `
        <td width="${cellWidths[cellIndex]}" valign="top" style="${rowBackground}font-family:Roboto,sans-serif;font-size:16px;color:#512B2B;line-height:24px;padding:12px 0;">
          ${cell.html || ""}
        </td>
    `;

      if (cellIndex + 1 < row.length) {
        tableHtml += `
        <td width="12" style="${rowBackground}">&nbsp;</td>
    `;
      }
    });

    tableHtml += `
        ${element.options.padding > 0 ? `<td width="20" style="${rowBackground}">&nbsp;</td>` : ""}
      </tr>
    `;
  }

  tableHtml += `</table>`;

  return tableHtml;
}

function getResolvedCellWidths(row: TABLE_CELL[], tableWidth = 560, gapWidth = 12): number[] {
  const gapCount = Math.max(row.length - 1, 0);
  const availableWidth = tableWidth - gapWidth * gapCount;

  const knownWidthTotal = row.reduce((sum, cell) => {
    return sum + (typeof cell.width === "number" ? cell.width : 0);
  }, 0);

  const missingWidthCount = row.filter(cell => typeof cell.width !== "number").length;

  if (missingWidthCount === 0) {
    return row.map(cell => cell.width!);
  }

  const fallbackWidth = Math.max(
    1,
    (availableWidth - knownWidthTotal) / missingWidthCount
  );

  return row.map(cell => {
    return typeof cell.width === "number" ? cell.width : fallbackWidth;
  });
}