<template>
  <v-menu
    v-model="menuOpen"
    :close-on-content-click="false"
    location="bottom"
  >
    <template #activator="{ props }">
      <v-btn
        v-bind="props"
        title="Link"
        :class="isLinkActive ? 'link-button-active' : ''"
        @click="openMenu"
      >
        <v-icon>{{ linkIcon }}</v-icon>
      </v-btn>
      <v-btn
        title="Remove link"
        :class="isLinkActive ? '' : 'fake-disabled'"
        @click="removeLinkFromMenu"
      >
        <v-icon>{{ removeLinkIcon }}</v-icon>
      </v-btn>
    </template>

    <v-card width="320" class="pa-3">
      <v-select
        v-model="linkType"
        label="Link type"
        density="compact"
        variant="outlined"
        hide-details
        :items="linkTypeOptions"
        class="mb-3"
      />

      <v-text-field
        v-model="linkInput"
        :label="linkInputLabel"
        density="compact"
        variant="outlined"
        hide-details
        autofocus
        class="mb-3"
        @keydown.enter.prevent="applyLinkFromMenu"
      />

      <div class="d-flex justify-space-between">
        <v-btn
          variant="text"
          :disabled="!isLinkActive"
          @click="removeLinkFromMenu"
        >
          Remove
        </v-btn>

        <div>
          <v-btn variant="text" @click="menuOpen = false">
            Cancel
          </v-btn>

          <v-btn color="black" variant="flat" @click="applyLinkFromMenu">
            Apply
          </v-btn>
        </div>
      </div>
    </v-card>
  </v-menu>
</template>

<script>
import { Extension } from '@tiptap/vue-3';
import { getMarkRange } from '@tiptap/core';
import Link from '@tiptap/extension-link';


// removes rel="noopener noreferrer nofollow" from links.
// https://github.com/iliyaZelenko/tiptap-vuetify/issues/250
export const CustomLink = Link.extend({
  addOptions() {
    return {
      openOnClick: false,
      linkOnPaste: true,
      autolink: true,
      protocols: ['tel', 'mailto'],
      HTMLAttributes: {
        target: '_blank',
        class: null,
        // rel: 'noopener noreferrer nofollow',
      },
      validate: undefined,
    }
  },
})

// adds style to links
export const StyledLink = Extension.create({
  name: "styledLink",

  addOptions: {
    types: ["link"]
  },

  addGlobalAttributes() {
    return [
      {
        types: this.options.types,
        attributes: {
          color: {
            default: null,
            renderHTML: () => {
              return {
                style: `font-family:Roboto,sans-serif;color:#257886;text-decoration:underline;`,
              };
            },
          }
        }
      }
    ];
  },
});

export default {
  name: 'LinkMenu',

  props: {
    editor: {
      type: Object,
      required: true,
    },
  },

  data() {
    return {
      menuOpen: false,
      linkType: 'url',
      linkInput: '',
      linkTypeOptions: [
        { title: 'Regular link', value: 'url' },
        { title: 'Phone', value: 'phone' },
        { title: 'Email', value: 'email' },
      ],
    }
  },

  computed: {
    currentLinkHref() {
      const href = this.editor?.getAttributes('link')?.href

      if (typeof href === 'string') {
        return href
      }

      if (href == null) {
        return ''
      }

      return String(href)
    },

    isLinkActive() {
      return this.editor?.isActive('link')
    },

    isPhoneLinkActive() {
      return this.isLinkActive && this.currentLinkHref.startsWith('tel:')
    },

    isMailLinkActive() {
      return this.isLinkActive && this.currentLinkHref.startsWith('mailto:')
    },

    linkInputLabel() {
      if (this.linkType === 'phone') return 'Phone number'
      if (this.linkType === 'email') return 'Email address'
      return 'URL'
    },

    activeLinkType() {
      if (this.isPhoneLinkActive) return 'phone'
      if (this.isMailLinkActive) return 'email'
      return 'url'
    },

    displayedLinkType() {
      return this.menuOpen ? this.linkType : this.activeLinkType
    },

    linkIcon() {
      if (this.displayedLinkType === 'phone') return 'mdi-phone'
      if (this.displayedLinkType === 'email') return 'mdi-email'
      return 'mdi-link'
    },

    removeLinkIcon() {
      if (this.displayedLinkType === 'phone') return 'mdi-phone-off'
      if (this.displayedLinkType === 'email') return 'mdi-email-off'
      return 'mdi-link-off'
    },
  },

  methods: {
    openMenu() {
      const href = this.currentLinkHref
      const selectedText = this.getSelectedText()

      const rawHref = href
        .replace(/^tel:/i, '')
        .replace(/^mailto:/i, '')

      const rawSelectedText = selectedText
        .replace(/^tel:/i, '')
        .replace(/^mailto:/i, '')

      if (href.startsWith('tel:')) {
        this.linkType = 'phone'
        this.linkInput = this.normalizePhoneNumber(rawHref)
      } else if (href.startsWith('mailto:')) {
        this.linkType = 'email'
        this.linkInput = this.normalizeEmailAddress(rawHref)
      } else if (href && this.looksLikePhoneNumber(href)) {
        this.linkType = 'phone'
        this.linkInput = this.normalizePhoneNumber(href)
      } else if (href && this.isValidEmail(href)) {
        this.linkType = 'email'
        this.linkInput = this.normalizeEmailAddress(href)
      } else if (selectedText && this.looksLikePhoneNumber(selectedText)) {
        this.linkType = 'phone'
        this.linkInput = this.normalizePhoneNumber(rawSelectedText)
      } else if (selectedText && this.isValidEmail(selectedText)) {
        this.linkType = 'email'
        this.linkInput = this.normalizeEmailAddress(rawSelectedText)
      } else if (href) {
        this.linkType = 'url'
        this.linkInput = this.normalizeUrl(href)
      } else {
        this.linkType = 'url'
        this.linkInput = this.normalizeUrl(selectedText)
      }

      this.menuOpen = true
    },

    applyLinkFromMenu() {
      const value = this.linkInput.trim()

      if (value === '') {
        this.removeLinkFromMenu()
        return
      }

      let href = ''

      if (this.linkType === 'phone') {
        href = `tel:${this.normalizePhoneNumber(value)}`
      } else if (this.linkType === 'email') {
        href = `mailto:${this.normalizeEmailAddress(value)}`
      } else {
        href = this.normalizeUrl(value)
      }

      this.applyLink(href)
      this.menuOpen = false
    },

    applyLink(href) {
      try {
        this.editor
          .chain()
          .focus()
          .extendMarkRange('link')
          .setLink({ href })
          .run()
      } catch (error) {
        console.error('Failed to apply link:', href, error)
      }
    },

    removeLinkFromMenu() {
      this.removeCurrentLink()
      this.menuOpen = false
    },

    removeCurrentLink() {
      const { state, view } = this.editor
      const { empty } = state.selection
      const linkType = state.schema.marks.link
      const href = this.currentLinkHref

      if (!empty) {
        this.editor
          .chain()
          .focus()
          .unsetMark('link')
          .run()

        return
      }

      const range = getMarkRange(state.selection.$from, linkType, { href })

      if (!range) {
        return
      }

      view.dispatch(
        state.tr.removeMark(range.from, range.to, linkType)
      )
    },

    getSelectedText() {
      const { from, to } = this.editor.state.selection

      if (from === to) {
        return ''
      }

      return this.editor.state.doc.textBetween(from, to, ' ').trim()
    },

    normalizeUrl(url) {
      const trimmedUrl = url.trim()

      if (!trimmedUrl) {
        return ''
      }

      if (/^(https?:\/\/|mailto:|tel:)/i.test(trimmedUrl)) {
        return trimmedUrl
      }

      if (/^www\./i.test(trimmedUrl)) {
        return `https://${trimmedUrl}`
      }

      if (this.looksLikeDomain(trimmedUrl)) {
        return `https://${trimmedUrl}`
      }

      return trimmedUrl
    },

    normalizePhoneNumber(phone) {
      const normalized = phone
        .trim()
        .replace(/\s+/g, '')
        .replace(/[()-]/g, '')

      if (normalized.startsWith('46') || normalized.startsWith('37')) {
        return `+${normalized}`
      }

      return normalized
    },

    looksLikeDomain(value) {
      return /^[a-z0-9-]+(\.[a-z0-9-]+)+([/?#].*)?$/i.test(value.trim())
    },

    normalizeEmailAddress(email) {
      return email.trim()
    },

    looksLikePhoneNumber(value) {
      return /^\+?[\d\s()-]+$/.test(value.trim())
    },

    isValidEmail(email) {
      const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
      return emailRegex.test(email);
    }
  },
}
</script>

<style lang="css" scoped>

.fake-disabled {
  pointer-events: none;
  opacity: 0.35;
}

.link-button-active {
  background-color: black;
  color: white;
}

</style>